let parties=[],activeParty=null;
function partyBalance(p,tx){return Number(p.opening_balance||0)+(tx||[]).reduce((s,x)=>s+(x.direction==="increase"?1:-1)*Number(x.amount||0),0);}
async function loadParties(){
 let partyRows,txRows;try{[partyRows,txRows]=await Promise.all([fetchAll("erp_parties"),fetchAll("erp_party_transactions")]);}catch(err){notice("تعذر تحميل العملاء والموردين: "+err.message,true);return;}
 parties=partyRows.sort((a,b)=>String(a.party_type).localeCompare(String(b.party_type))||String(a.name).localeCompare(String(b.name)));const sums={};txRows.forEach(x=>{sums[x.party_id]=(sums[x.party_id]||0)+(x.direction==="increase"?1:-1)*Number(x.amount);});
 const q=$("#party-search").value.trim().toLowerCase();
 $("#parties-body").innerHTML=parties.filter(p=>(p.name+" "+(p.phone||"")).toLowerCase().includes(q)).map(p=>"<tr><td>"+(p.party_type==="customer"?"عميل":"مورد")+"</td><td>"+esc(p.name)+"</td><td>"+esc(p.phone||"—")+"</td><td>"+money(p.opening_balance)+"</td><td>"+money(Number(p.opening_balance||0)+(sums[p.id]||0))+"</td><td><button class='secondary party-open' data-id='"+p.id+"'>فتح الكشف</button> "+(p.party_type==="supplier"?"<button class='secondary supplier-purchases-open' data-id='"+p.id+"'>مشتريات المورد</button>":"")+"</td></tr>").join("")||"<tr><td colspan='6'>لا توجد بيانات مطابقة.</td></tr>";
}
