$("#parties-body").onclick=e=>{const b=e.target.closest(".party-open"),s=e.target.closest(".supplier-purchases-open");if(b)openParty(b.dataset.id);if(s)openSupplierPurchases(s.dataset.id);};
$("#party-form").onsubmit=async e=>{e.preventDefault();const row={owner_id:session.user.id,party_type:$("#party-type").value,name:$("#party-name").value.trim(),phone:$("#party-phone").value.trim()||null,address:$("#party-address").value.trim()||null,opening_balance:Number($("#party-opening").value||0),notes:$("#party-notes").value.trim()||null};const {error}=await db.from("erp_parties").insert(row);if(error){notice("تعذر حفظ البيانات: "+error.message,true);return;}notice("تم حفظ بيانات الطرف بنجاح.");$("#party-form").reset();$("#party-form-panel").hidden=true;await loadParties();};
async function openParty(id){
 activeParty=parties.find(p=>p.id===id);if(!activeParty)return;
 $("#party-ledger-panel").hidden=false;$("#party-ledger-title").textContent="كشف حساب: "+activeParty.name;
 $("#party-tx-date").value=localDate();$("#party-tx-direction").innerHTML=activeParty.party_type==="customer"?"<option value='increase'>مديونية جديدة على العميل</option><option value='decrease'>تحصيل من العميل</option>":"<option value='increase'>مبلغ مستحق للمورد</option><option value='decrease'>سداد للمورد</option>";
 await refreshPartyLedger();$("#party-ledger-panel").scrollIntoView({behavior:"smooth",block:"start"});
}
async function refreshPartyLedger(){
 if(!activeParty)return;const {data,error}=await db.from("erp_party_transactions").select("*").eq("party_id",activeParty.id).order("transaction_date",{ascending:false}).order("created_at",{ascending:false});
 if(error){notice(error.message,true);return;}const rows=data||[],balance=partyBalance(activeParty,rows);
 $("#party-ledger-balance").textContent=(activeParty.party_type==="customer"?"المبلغ المستحق لك من العميل: ":"المبلغ المستحق للمورد: ")+money(balance);
 $("#party-ledger-body").innerHTML=rows.map(x=>"<tr><td>"+esc(x.transaction_date)+"</td><td>"+esc(x.description)+"</td><td>"+(x.direction==="increase"?money(x.amount):"—")+"</td><td>"+(x.direction==="decrease"?money(x.amount):"—")+"</td></tr>").join("")||"<tr><td colspan='4'>لا توجد حركات مسجلة.</td></tr>";
}
$("#party-ledger-close").onclick=()=>{$("#party-ledger-panel").hidden=true;activeParty=null;};
$("#party-tx-form").onsubmit=async e=>{e.preventDefault();if(!activeParty)return;const row={owner_id:session.user.id,party_id:activeParty.id,transaction_date:$("#party-tx-date").value,direction:$("#party-tx-direction").value,amount:Number($("#party-tx-amount").value),description:$("#party-tx-description").value.trim()};const {error}=await db.from("erp_party_transactions").insert(row);if(error){notice("تعذر حفظ الحركة: "+error.message,true);return;}notice("تم تسجيل الحركة في كشف الحساب.");$("#party-tx-form").reset();$("#party-tx-date").value=localDate();await refreshPartyLedger();await loadParties();};

function purchaseInvoiceNo(){return "PUR-"+localDate().replaceAll("-","")+"-"+String(Date.now()).slice(-6);}
let purchaseProducts=[],purchaseTrackedProductIds=new Set();
function purchaseAddLine(){
 const opts='<option value="">اختر المنتج</option>'+purchaseProducts.map(p=>'<option value="'+p.id+'">'+esc(p.name)+'</option>').join("");
 const tr=document.createElement("tr");tr.innerHTML='<td><select class="purchase-product">'+opts+'</select><label class="imei-toggle"><input class="purchase-track-imei" type="checkbox"> تتبع IMEI</label><textarea class="purchase-imeis" rows="2" placeholder="جهاز واحد في كل سطر: IMEI الأول، والثاني اختياري" hidden></textarea><small class="muted imei-help">فعّل التتبع للأجهزة التي لها أرقام IMEI.</small></td><td><input class="purchase-qty" type="number" min="1" step="1" value="1"></td><td><input class="purchase-cost" type="number" min="0" step="0.01" value="0"></td><td class="purchase-line-total">0.00</td><td><button type="button" class="secondary purchase-remove">حذف</button></td>';
 $("#purchase-lines").appendChild(tr);purchaseCalc();
}
function purchaseCalc(){
 let subtotal=0,totalQty=0;const lineRows=[...document.querySelectorAll("#purchase-lines tr")];lineRows.forEach(tr=>{const q=Number(tr.querySelector(".purchase-qty").value||0),c=Number(tr.querySelector(".purchase-cost").value||0),v=q*c;subtotal+=v;totalQty+=q;tr.querySelector(".purchase-line-total").textContent=money(v);});
 $("#purchase-items-count").textContent="عدد الأصناف المختلفة: "+lineRows.filter(tr=>tr.querySelector(".purchase-product").value).length+" — إجمالي عدد القطع: "+totalQty;
 const total=Math.max(0,subtotal-Number($("#purchase-discount").value||0)),paid=["drawer","vodafone","instapay"].reduce((s,k)=>s+Number($("#purchase-pay-"+k).value||0),0);
 $("#purchase-total").textContent=money(total);$("#purchase-paid").textContent=money(paid);$("#purchase-remaining").textContent="المتبقي: "+money(Math.max(0,total-paid));
}
async function openSupplierPurchases(id){
 const supplier=parties.find(p=>p.id===id&&p.party_type==="supplier");if(!supplier)return;
 $("#supplier-purchases-panel").hidden=false;$("#supplier-purchases-title").textContent="مشتريات المورد: "+supplier.name;
 $("#supplier-purchases-summary").textContent="جاري تحميل فواتير وأصناف المورد...";
 $("#supplier-purchases-body").innerHTML="<tr><td colspan='7'>جاري التحميل...</td></tr>";
 $("#supplier-purchases-panel").scrollIntoView({behavior:"smooth",block:"start"});
 const {data:invoices,error}=await db.from("erp_purchase_invoices").select("id,invoice_no,invoice_date,total,paid,remaining").eq("supplier_id",id).order("invoice_date",{ascending:false});
 if(error){notice("تعذر تحميل مشتريات المورد: "+error.message,true);return;}
 const ids=(invoices||[]).map(x=>x.id);
 if(!ids.length){$("#supplier-purchases-summary").textContent="لا توجد فواتير شراء مسجلة لهذا المورد.";$("#supplier-purchases-body").innerHTML="<tr><td colspan='7'>لا توجد مشتريات.</td></tr>";return;}
 const {data:items,error:itemError}=await db.from("erp_purchase_invoice_items").select("invoice_id,product_name,quantity,unit_cost,line_total").in("invoice_id",ids);
 if(itemError){notice("تعذر تحميل أصناف فواتير المورد: "+itemError.message,true);return;}
 const byId={};(invoices||[]).forEach(x=>byId[x.id]=x);
 const rows=(items||[]).map(x=>{const inv=byId[x.invoice_id]||{};return "<tr><td>"+esc(inv.invoice_no||"—")+"</td><td>"+esc(inv.invoice_date||"—")+"</td><td>"+esc(x.product_name)+"</td><td>"+Number(x.quantity||0)+"</td><td>"+money(x.unit_cost)+"</td><td>"+money(x.line_total)+"</td><td>"+money(inv.remaining)+"</td></tr>";});
 const qty=(items||[]).reduce((s,x)=>s+Number(x.quantity||0),0),sum=(invoices||[]).reduce((s,x)=>s+Number(x.total||0),0),paid=(invoices||[]).reduce((s,x)=>s+Number(x.paid||0),0);
 $("#supplier-purchases-summary").textContent="عدد الفواتير: "+invoices.length+" — عدد الأصناف المسجلة: "+items.length+" — إجمالي القطع: "+qty+" — إجمالي المشتريات: "+money(sum)+" — المدفوع: "+money(paid)+" — المتبقي: "+money(sum-paid);
 $("#supplier-purchases-body").innerHTML=rows.join("")||"<tr><td colspan='7'>الفواتير موجودة لكن لا توجد تفاصيل أصناف.</td></tr>";
}
$("#supplier-purchases-close").onclick=()=>{$("#supplier-purchases-panel").hidden=true;};
async function loadPurchases(){
 const [pr,sr,ir]=await Promise.all([
  db.from("erp_products").select("id,name,quantity,cost_price").order("name"),
  db.from("erp_parties").select("id,name").eq("party_type","supplier").order("name"),
  db.from("erp_purchase_invoices").select("*").order("created_at",{ascending:false}).limit(100)
 ]);
 if(pr.error||sr.error||ir.error){notice("تعذر تحميل المشتريات: "+(pr.error||sr.error||ir.error).message,true);return;}
 purchaseProducts=pr.data||[];
 try{const units=await fetchAll("erp_product_units");purchaseTrackedProductIds=new Set(units.map(u=>u.product_id));}catch(e){notice("تعذر تحميل حالة تتبع IMEI: "+e.message,true);return;}
 $("#purchase-supplier").innerHTML='<option value="">مورد نقدي / غير محدد</option>'+(sr.data||[]).map(x=>'<option value="'+x.id+'">'+esc(x.name)+'</option>').join("");
 $("#purchase-no").value=purchaseInvoiceNo();$("#purchase-date").value=localDate();
 if(!$("#purchase-lines").children.length)purchaseAddLine();
 const invoiceIds=(ir.data||[]).map(x=>x.id);let itemStats={};
 if(invoiceIds.length){const {data:its,error:itemsError}=await db.from("erp_purchase_invoice_items").select("invoice_id,quantity").in("invoice_id",invoiceIds);if(itemsError){notice("تعذر تحميل عدد الأصناف في فواتير الشراء: "+itemsError.message,true);return;}(its||[]).forEach(it=>{if(!itemStats[it.invoice_id])itemStats[it.invoice_id]={lines:0,qty:0};itemStats[it.invoice_id].lines++;itemStats[it.invoice_id].qty+=Number(it.quantity||0);});}
 $("#purchases-body").innerHTML=(ir.data||[]).map(x=>{const st=itemStats[x.id]||{lines:0,qty:0};return "<tr><td>"+esc(x.invoice_no)+"</td><td>"+esc(x.invoice_date)+"</td><td>"+esc(x.supplier_name||"مورد نقدي")+"</td><td>"+st.lines+" صنف / "+st.qty+" قطعة</td><td>"+money(x.total)+"</td><td>"+money(x.paid)+"</td><td>"+money(x.remaining)+"</td><td><button class=\"secondary print-purchase\" data-id=\""+x.id+"\">طباعة</button></td></tr>";}).join("")||"<tr><td colspan='8'>لا توجد فواتير شراء.</td></tr>";
}
$("#purchase-add-line").onclick=purchaseAddLine;
$("#purchase-lines").oninput=e=>{if(e.target.classList.contains("purchase-imeis"))return;purchaseCalc();};
$("#purchase-lines").onchange=e=>{
 const tr=e.target.closest("tr");
 if(e.target.classList.contains("purchase-product")&&tr){const checked=purchaseTrackedProductIds.has(e.target.value);tr.querySelector(".purchase-track-imei").checked=checked;tr.querySelector(".purchase-imeis").hidden=!checked;}
 if(e.target.classList.contains("purchase-track-imei")&&tr)tr.querySelector(".purchase-imeis").hidden=!e.target.checked;
 purchaseCalc();
};
$("#purchase-lines").onclick=e=>{if(e.target.classList.contains("purchase-remove")){e.target.closest("tr").remove();purchaseCalc();}};
["purchase-discount","purchase-pay-drawer","purchase-pay-vodafone","purchase-pay-instapay"].forEach(id=>$("#"+id).oninput=purchaseCalc);
$("#purchase-form").onsubmit=async e=>{
 e.preventDefault();const rows=[...document.querySelectorAll("#purchase-lines tr")];
 const items=rows.map(tr=>{
  const quantity=Number(tr.querySelector(".purchase-qty").value),track=tr.querySelector(".purchase-track-imei").checked,raw=tr.querySelector(".purchase-imeis").value;
  const imei_units=track?raw.split(/\\r?\\n/).map(line=>{const nums=(line.match(/[0-9٠-٩]{15}/g)||[]).map(digits);return nums.length?{imei1:nums[0],imei2:nums[1]||null}:null;}).filter(Boolean):[];
  return {product_id:tr.querySelector(".purchase-product").value,quantity,unit_cost:Number(tr.querySelector(".purchase-cost").value),imei_units};
 });
 if(items.some(x=>!x.product_id||!Number.isInteger(x.quantity)||x.quantity<1||!Number.isFinite(x.unit_cost)||x.unit_cost<0)){notice("راجع الأصناف والكميات وتكلفة الشراء.",true);return;}
 for(let i=0;i<items.length;i++){
  const item=items[i],tr=rows[i];
  if(tr.querySelector(".purchase-track-imei").checked){
   const raw=tr.querySelector(".purchase-imeis").value,lines=raw.split(/\\r?\\n/).filter(x=>x.trim());
   const serials=item.imei_units.flatMap(x=>[x.imei1,x.imei2].filter(Boolean));
   if(lines.length!==item.quantity||item.imei_units.length!==item.quantity||serials.some(x=>!luhn(x))||new Set(serials).size!==serials.length){notice("أدخل سطرًا لكل جهاز، وكل سطر يحتوي IMEI صحيحًا من 15 رقمًا (والثاني اختياري)، بدون تكرار.",true);return;}
  }else if(purchaseTrackedProductIds.has(item.product_id)){notice("هذا الصنف مسجل بتتبع IMEI؛ فعّل التتبع وأدخل أرقام الأجهزة.",true);return;}
 }
 const payments=[["drawer","purchase-pay-drawer"],["vodafone_cash","purchase-pay-vodafone"],["instapay","purchase-pay-instapay"]].map(([account_code,id])=>({account_code,amount:Number($("#"+id).value||0)}));
 const args={p_invoice_no:$("#purchase-no").value.trim(),p_invoice_date:$("#purchase-date").value,p_supplier_id:$("#purchase-supplier").value||null,p_discount:Number($("#purchase-discount").value||0),p_notes:$("#purchase-notes").value.trim()||null,p_items:items,p_payments:payments};
 const btn=e.submitter;if(btn)btn.disabled=true;
 try{const {error}=await db.rpc("erp_create_purchase",args);if(error)throw error;notice("تم حفظ فاتورة الشراء، وزادت الكميات وتم تحديث متوسط تكلفة الأصناف وتسجيل المدفوع.");$("#purchase-form").reset();$("#purchase-lines").innerHTML="";$("#purchase-discount").value=0;["drawer","vodafone","instapay"].forEach(k=>$("#purchase-pay-"+k).value=0);$("#purchase-no").value=purchaseInvoiceNo();$("#purchase-date").value=localDate();await loadPurchases();await loadCashbox();await dashboard();}
 catch(err){notice("لم يتم حفظ فاتورة الشراء: "+(err.message||err),true);}
 finally{if(btn)btn.disabled=false;}
};

