async function loadExpenses(){ $("#expense-date").value=localDate();let data;try{data=await fetchAll("erp_expenses");data.sort((a,b)=>String(b.expense_date).localeCompare(String(a.expense_date)));}catch(error){notice("نفّذ accounting/upgrade-07.sql لتفعيل المصروفات: "+error.message,true);return;}const names={drawer:"درج الكاش",vodafone_cash:"فودافون كاش",instapay:"إنستا باي"};$("#expenses-body").innerHTML=(data||[]).map(x=>"<tr><td>"+esc(x.expense_date)+"</td><td>"+esc(x.category)+"</td><td>"+esc(x.description)+"</td><td>"+(names[x.account_code]||x.account_code)+"</td><td>"+money(x.amount)+"</td></tr>").join("")||"<tr><td colspan='5'>لا توجد مصروفات مسجلة.</td></tr>";}
$("#expense-form").onsubmit=async e=>{e.preventDefault();const row={p_expense_date:$("#expense-date").value,p_category:$("#expense-category").value,p_amount:Number($("#expense-amount").value),p_account_code:$("#expense-account").value,p_description:$("#expense-description").value.trim()};const b=e.submitter;if(b)b.disabled=true;try{const {error}=await db.rpc("erp_record_expense",row);if(error)throw error;notice("تم حفظ المصروف وخصمه من الحساب المختار.");$("#expense-form").reset();$("#expense-date").value=localDate();await loadExpenses();await loadCashbox();}catch(err){notice("تعذر تسجيل المصروف: "+err.message,true);}finally{if(b)b.disabled=false;}};
async function loadReports(){const today=localDate();$("#report-from").value=$("#report-from").value||today.slice(0,8)+"01";$("#report-to").value=$("#report-to").value||today;await buildReport();}
$("#report-form").onsubmit=async e=>{e.preventDefault();await buildReport();};
async function buildReport(){
 const from=$("#report-from").value,to=$("#report-to").value;
 if(!from||!to||from>to){notice("راجع تاريخ بداية ونهاية التقرير.",true);return;}
 try{
  const [allSales,allSaleItems,allPurchases,allExpenses,allReturns]=await Promise.all([
   fetchAll("erp_sales_invoices"),fetchAll("erp_sales_invoice_items"),fetchAll("erp_purchase_invoices"),fetchAll("erp_expenses"),fetchAll("erp_returns")
  ]);
  const invoices=allSales.filter(v=>v.invoice_date>=from&&v.invoice_date<=to&&v.status!=="cancelled");
  const ids=new Set(invoices.map(v=>v.id));
  const items=allSaleItems.filter(v=>ids.has(v.invoice_id));
  const returns=allReturns.filter(v=>v.return_date>=from&&v.return_date<=to);
  const saleReturns=returns.filter(x=>x.return_type==="sale"),purchaseReturns=returns.filter(x=>x.return_type==="purchase");
  const salesGross=invoices.reduce((a,v)=>a+Number(v.total||0),0);
  const salesReturnTotal=saleReturns.reduce((a,v)=>a+Number(v.total||0),0);
  const costGross=items.reduce((a,v)=>a+Number(v.quantity||0)*Number(v.unit_cost||0),0);
  const purchaseGross=allPurchases.filter(v=>v.invoice_date>=from&&v.invoice_date<=to).reduce((a,v)=>a+Number(v.total||0),0);
  const purchaseReturnTotal=purchaseReturns.reduce((a,v)=>a+Number(v.total||0),0);
  const returnedCostIds=saleReturns.map(x=>x.id);let returnedCost=0;
  if(returnedCostIds.length){const {data,error}=await db.from("erp_return_items").select("quantity,unit_cost").in("return_id",returnedCostIds);if(error)throw error;returnedCost=(data||[]).reduce((a,v)=>a+Number(v.quantity||0)*Number(v.unit_cost||0),0);}
  const sales=salesGross-salesReturnTotal,cost=costGross-returnedCost,purchases=purchaseGross-purchaseReturnTotal;
  const expenses=allExpenses.filter(v=>v.expense_date>=from&&v.expense_date<=to).reduce((a,v)=>a+Number(v.amount||0),0);
  $("#report-sales").textContent=money(sales);$("#report-purchases").textContent=money(purchases);$("#report-expenses").textContent=money(expenses);$("#report-profit").textContent=money(sales-cost-expenses);
  $("#report-note").textContent="الفترة: "+from+" إلى "+to+" — صافي المبيعات بعد المرتجعات: "+money(sales)+"، وتكلفة البضاعة المباعة بعد عكس تكلفة مرتجعات البيع: "+money(cost)+". الربح تقديري ويعكس حركة الفترة؛ قد تظهر تكلفة بضاعة سالبة عند رد بضاعة مباعة في فترة سابقة. لا يشمل أرباح فوري أو إيرادات الصيانة أو الضرائب. يشمل التقرير فواتير الشراء والمرتجعات المسجلة خلال الفترة.";
 }catch(err){notice("تعذر تحميل التقرير: "+err.message,true);}
}


function downloadFile(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);}
function csvCell(v){if(v===null||v===undefined)return '""';let s=typeof v==="object"?JSON.stringify(v):String(v);return '"'+s.replace(/"/g,'""')+'"';}
async function fetchAll(table){let out=[],from=0;while(true){const {data,error}=await db.from(table).select("*").range(from,from+999);if(error)throw error;out=out.concat(data||[]);if(!data||data.length<1000)break;from+=1000;}return out;}
$("#backup-json").onclick=async()=>{const b=$("#backup-json");b.disabled=true;try{const tables=["erp_products","erp_product_units","erp_sales_invoices","erp_sales_invoice_items","erp_sales_payments","erp_purchase_invoices","erp_purchase_invoice_items","erp_purchase_payments","erp_parties","erp_party_transactions","erp_cash_accounts","erp_cash_movements","erp_fawry_transactions","erp_fawry_daily_closings","erp_maintenance_orders","erp_expenses","erp_shop_settings","erp_returns","erp_return_items","erp_stock_counts","erp_stock_count_items","erp_cash_transfers"];const backup={app:"AL GABAS STORE",exported_at:new Date().toISOString(),tables:{}};for(const t of tables){try{backup.tables[t]=await fetchAll(t);}catch(e){if(!/does not exist|Could not find the table/i.test(e.message))throw e;backup.tables[t]=[];}}downloadFile("AL-GABAS-STORE-backup-"+localDate()+".json",JSON.stringify(backup,null,2),"application/json;charset=utf-8");notice("تم تجهيز النسخة الاحتياطية وتنزيلها. احتفظ بالملف في مكان آمن.");}catch(e){notice("تعذر إنشاء النسخة الاحتياطية: "+e.message,true);}finally{b.disabled=false;}};
$("#export-csv").onclick=async()=>{const b=$("#export-csv"),t=$("#export-table").value;b.disabled=true;try{const rows=await fetchAll(t);if(!rows.length){notice("لا توجد بيانات في الجدول المحدد.",true);return;}const cols=[...new Set(rows.flatMap(x=>Object.keys(x)))];const csv="\uFEFF"+[cols.map(csvCell).join(","),...rows.map(x=>cols.map(c=>csvCell(x[c])).join(","))].join("\r\n");downloadFile(t+"-"+localDate()+".csv",csv,"text/csv;charset=utf-8");notice("تم تنزيل ملف CSV.");}catch(e){notice("تعذر التصدير: "+e.message,true);}finally{b.disabled=false;}};
async function loadStocktake(){const d=localDate();$("#stocktake-date").value=d;await loadProducts();renderStocktake();const {data,error}=await db.from("erp_stock_counts").select("id,count_date,notes").order("created_at",{ascending:false}).limit(30);if(error){notice("نفّذ accounting/upgrade-08.sql لتفعيل الجرد: "+error.message,true);return;}const body=$("#stocktake-history");body.innerHTML=(data||[]).map(x=>"<tr><td>"+esc(x.count_date)+"</td><td><button class='secondary stock-count-detail' data-id='"+x.id+"'>عرض الأصناف</button></td><td>"+esc(x.notes||"—")+"</td></tr>").join("")||"<tr><td colspan='3'>لا توجد عمليات جرد.</td></tr>";}
function renderStocktake(){const body=$("#stocktake-body");body.innerHTML=(products||[]).map(p=>"<tr data-product='"+p.id+"'><td>"+esc(p.name)+"</td><td class='system-qty'>"+Number(p.quantity||0)+"</td><td><input class='counted-qty' type='number' min='0' step='1' value='"+Number(p.quantity||0)+"' style='width:100px'></td><td class='count-diff'>0</td></tr>").join("")||"<tr><td colspan='4'>لا توجد منتجات.</td></tr>";body.oninput=e=>{if(e.target.classList.contains("counted-qty")){const tr=e.target.closest("tr");tr.querySelector(".count-diff").textContent=Number(e.target.value||0)-Number(tr.querySelector(".system-qty").textContent);}};}
$("#stocktake-refresh").onclick=async()=>{await loadProducts();renderStocktake();};
$("#stocktake-form").onsubmit=async e=>{e.preventDefault();const rows=[...$("#stocktake-body").querySelectorAll("tr[data-product]")];if(!rows.length){notice("لا توجد منتجات للجرد.",true);return;}const items=rows.map(tr=>({product_id:tr.dataset.product,counted_quantity:Number(tr.querySelector(".counted-qty").value)}));if(items.some(x=>!Number.isInteger(x.counted_quantity)||x.counted_quantity<0)){notice("راجع الكميات الفعلية.",true);return;}const b=e.submitter;if(b)b.disabled=true;try{const {error}=await db.rpc("erp_post_stock_count",{p_count_date:$("#stocktake-date").value,p_notes:$("#stocktake-notes").value.trim(),p_items:items});if(error)throw error;notice("تم حفظ الجرد وتسوية كميات المخزون.");await loadStocktake();await loadProducts();await dashboard();}catch(err){notice("تعذر حفظ الجرد: "+err.message,true);}finally{if(b)b.disabled=false;}};
$("#stocktake-history").onclick=async e=>{const b=e.target.closest(".stock-count-detail");if(!b)return;const {data,error}=await db.from("erp_stock_count_items").select("*").eq("count_id",b.dataset.id);if(error){notice(error.message,true);return;}const txt=(data||[]).map(x=>x.product_name+": "+x.system_quantity+" ← "+x.counted_quantity+" (فرق "+x.difference+")").join("\n");alert(txt||"لا توجد تفاصيل.");};
let returnInvoiceItems=[];
function returnNo(){return "RET-"+localDate().replaceAll("-","")+"-"+String(Date.now()).slice(-5);}
async function loadReturns(){const type=$("#return-type").value;$("#return-date").value=localDate();$("#return-no").value=returnNo();$("#return-refund-box").hidden=type!=="sale";$("#return-invoice").innerHTML='<option value="">جاري تحميل الفواتير...</option>';const table=type==="sale"?"erp_sales_invoices":"erp_purchase_invoices";const {data,error}=await db.from(table).select(type==="sale"?"id,invoice_no,invoice_date,total,customer_name,status":"id,invoice_no,invoice_date,total,supplier_name").order("invoice_date",{ascending:false}).limit(300);if(error){notice("تعذر تحميل فواتير المرتجعات: "+error.message,true);return;}const rows=(data||[]).filter(x=>type!=="sale"||x.status==="completed");$("#return-invoice").innerHTML='<option value="">اختر الفاتورة</option>'+rows.map(x=>'<option value="'+x.id+'">'+esc(x.invoice_no)+" — "+esc(type==="sale"?x.customer_name:x.supplier_name)+" — "+esc(x.invoice_date)+" — "+money(x.total)+'</option>').join("");$("#return-items").innerHTML="";const {data:history,error:he}=await db.from("erp_returns").select("*").order("created_at",{ascending:false}).limit(100);if(he){notice(he.message,true);return;}const saleIds=[...new Set((history||[]).filter(x=>x.return_type==="sale").map(x=>x.invoice_id))],purchaseIds=[...new Set((history||[]).filter(x=>x.return_type==="purchase").map(x=>x.invoice_id))],invoiceNames={};if(saleIds.length){const {data:d,error:e}=await db.from("erp_sales_invoices").select("id,invoice_no").in("id",saleIds);if(e){notice(e.message,true);return;}(d||[]).forEach(x=>invoiceNames[x.id]=x.invoice_no);}if(purchaseIds.length){const {data:d,error:e}=await db.from("erp_purchase_invoices").select("id,invoice_no").in("id",purchaseIds);if(e){notice(e.message,true);return;}(d||[]).forEach(x=>invoiceNames[x.id]=x.invoice_no);}$("#returns-history").innerHTML=(history||[]).map(x=>"<tr><td>"+esc(x.return_no)+"</td><td>"+(x.return_type==="sale"?"مرتجع بيع":"مرتجع شراء")+"</td><td>"+esc(x.return_date)+"</td><td>"+esc(invoiceNames[x.invoice_id]||"فاتورة غير متاحة")+"</td><td>"+money(x.total)+"</td></tr>").join("")||"<tr><td colspan='5'>لا توجد مرتجعات.</td></tr>";}
$("#return-type").onchange=loadReturns;
$("#return-invoice").onchange=async()=>{const id=$("#return-invoice").value,type=$("#return-type").value;$("#return-items").innerHTML="";if(!id)return;const table=type==="sale"?"erp_sales_invoice_items":"erp_purchase_invoice_items",price=type==="sale"?"unit_price":"unit_cost";const {data,error}=await db.from(table).select("id,product_id,product_name,quantity,"+price).eq("invoice_id",id);if(error){notice(error.message,true);return;}const {data:returned,error:re}=await db.from("erp_returns").select("id").eq("invoice_id",id).eq("return_type",type);if(re){notice(re.message,true);return;}const ids=(returned||[]).map(x=>x.id);let sums={};if(ids.length){const {data:ri,error:rie}=await db.from("erp_return_items").select("invoice_item_id,quantity").in("return_id",ids);if(rie){notice(rie.message,true);return;}(ri||[]).forEach(x=>sums[x.invoice_item_id]=(sums[x.invoice_item_id]||0)+Number(x.quantity));}returnInvoiceItems=(data||[]).map(x=>({...x,price:Number(x[price]||0),returned:sums[x.id]||0}));$("#return-items").innerHTML=returnInvoiceItems.map(x=>"<tr data-item='"+x.id+"'><td>"+esc(x.product_name)+"</td><td>"+x.quantity+"</td><td>"+x.returned+"</td><td><input class='return-qty' type='number' min='0' max='"+Math.max(0,x.quantity-x.returned)+"' value='0' step='1' style='width:85px'></td><td>"+money(x.price)+"</td></tr>").join("")||"<tr><td colspan='5'>لا توجد أصناف.</td></tr>";};
$("#return-form").onsubmit=async e=>{e.preventDefault();const id=$("#return-invoice").value;if(!id){notice("اختر الفاتورة الأصلية.",true);return;}const items=[...$("#return-items").querySelectorAll("tr[data-item]")].map(tr=>({invoice_item_id:tr.dataset.item,quantity:Number(tr.querySelector(".return-qty").value)})).filter(x=>x.quantity>0);if(!items.length){notice("حدد كمية مرتجع لصنف واحد على الأقل.",true);return;}const type=$("#return-type").value;const payments=[["drawer","return-pay-drawer"],["vodafone_cash","return-pay-vodafone"],["instapay","return-pay-instapay"]].map(([account_code,k])=>({account_code,amount:Number($("#"+k).value||0)}));const b=e.submitter;if(b)b.disabled=true;try{const {error}=await db.rpc("erp_post_return",{p_return_no:$("#return-no").value.trim(),p_return_type:type,p_invoice_id:id,p_return_date:$("#return-date").value,p_notes:$("#return-notes").value.trim(),p_items:items,p_refund_payments:payments});if(error)throw error;notice("تم حفظ المرتجع وتحديث المخزون"+(type==="sale"?" وتسجيل رد المبلغ في الخزنة.":" وتحديث حساب المورد.") );$("#return-form").reset();$("#return-items").innerHTML="";await loadReturns();await loadProducts();await loadCashbox();await dashboard();}catch(err){notice("تعذر حفظ المرتجع: "+err.message,true);}finally{if(b)b.disabled=false;}};
async function printInvoice(type,id){let w=null;try{w=window.open("","_blank");if(!w){notice("اسمح بفتح النوافذ المنبثقة لطباعة الفاتورة.",true);return;}w.document.write("<!doctype html><html lang='ar' dir='rtl'><meta charset='utf-8'><body style='font-family:Arial;text-align:center;padding:30px'>جاري تجهيز الفاتورة...</body></html>");const sales=type==="sale",head=sales?"erp_sales_invoices":"erp_purchase_invoices",itemsTable=sales?"erp_sales_invoice_items":"erp_purchase_invoice_items";const [{data:inv,error:ie},{data:items,error:ite},{data:settings}]=await Promise.all([db.from(head).select("*").eq("id",id).single(),db.from(itemsTable).select("*").eq("invoice_id",id),db.from("erp_shop_settings").select("*").maybeSingle()]);if(ie||ite)throw ie||ite;const s=settings||{},title=s.shop_name||"الجباس ستور",person=sales?inv.customer_name:inv.supplier_name;const rows=(items||[]).map(x=>"<tr><td>"+esc(x.product_name)+"</td><td>"+x.quantity+"</td><td>"+money(sales?x.unit_price:x.unit_cost)+"</td><td>"+money(x.line_total)+"</td></tr>").join("");w.document.write("<!doctype html><html lang='ar' dir='rtl'><meta charset='utf-8'><title>"+esc(inv.invoice_no)+"</title><style>body{font-family:Arial,sans-serif;padding:24px;color:#111}h1{text-align:center}p{text-align:center}table{width:100%;border-collapse:collapse;margin-top:20px}td,th{border:1px solid #aaa;padding:9px;text-align:right}.sum{margin-top:18px;font-weight:bold}.foot{text-align:center;margin-top:40px}</style><h1>"+esc(title)+"</h1><p>"+esc(s.shop_name_en||"AL GABAS STORE")+"<br>"+esc(s.address||"")+"<br>"+esc(s.phone||"")+"</p><hr><h2>"+(sales?"فاتورة بيع":"فاتورة شراء")+"</h2><p>رقم الفاتورة: "+esc(inv.invoice_no)+"　 التاريخ: "+esc(inv.invoice_date)+"<br>"+(sales?"العميل: ":"المورد: ")+esc(person||"—")+"</p><table><thead><tr><th>الصنف</th><th>الكمية</th><th>سعر الوحدة</th><th>الإجمالي</th></tr></thead><tbody>"+rows+"</tbody></table><div class='sum'>الإجمالي: "+money(inv.total)+"<br>المدفوع: "+money(inv.paid)+"<br>المتبقي: "+money(inv.remaining)+"</div><p class='foot'>"+esc(s.invoice_note||"شكراً لتعاملكم معنا")+"</p><script>window.onload=()=>window.print()<\/script></html>");w.document.close();}catch(e){if(w&&!w.closed)w.close();notice("تعذرت طباعة الفاتورة: "+e.message,true);}}
